INSERT INTO cms.article (id, slug, title_en, title_ar, excerpt_en, excerpt_ar, body_en, body_ar, body_html_en, body_html_ar, cover_url, seo_title_en, seo_title_ar, seo_description_en, seo_description_ar, category, tags, author_name, status, publish_at, featured, created_at, updated_at) VALUES ('art-1', 'zayed-group-2026-outlook', 'Zayed Group 2026 GCC Market Outlook & Benchmarks', 'توقعات أسواق الخليج ومعايير الأداء لعام 2026 — مجموعة زايد', 'Key operational benchmarks, real metrics, and 2026 guidance from Zayed Group in Manama.', 'أبرز المعايير التشغيلية والأرقام الموثقة وإرشادات 2026 من مجموعة زايد في Manama.', '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Diversified Bahraini holding group operating retail storefronts, last-mile fleet logistics, media production, and enterprise advisory. Focusing on Enterprise Turnkey Operations Retainer, our teams help Gulf enterprises scale reliably."}]}]}'::jsonb, '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"مجموعة بحرينية متنوعة الأنشطة تدير المتاجر الإلكترونية والأسطول اللوجستي والإنتاج الإعلامي والاستشارات. من خلال خدمة إدارة العمليات المؤسسية الشاملة نساعد المؤسسات على النمو المستدام."}]}]}'::jsonb, '<p>Diversified Bahraini holding group operating retail storefronts, last-mile fleet logistics, media production, and enterprise advisory.</p><p>Focusing on <strong>Enterprise Turnkey Operations Retainer</strong>, our Manama specialists help Gulf organizations standardize turnaround times and audit transparency.</p>', '<p>مجموعة بحرينية متنوعة الأنشطة تدير المتاجر الإلكترونية والأسطول اللوجستي والإنتاج الإعلامي والاستشارات.</p><p>من خلال خدمة <strong>إدارة العمليات المؤسسية الشاملة</strong>، يعمل فريقنا في Manama على توحيد سرعة التسليم ووضوح التدقيق.</p>', '/api/files/media/banners/banner-01.png', 'Zayed Group 2026 GCC Market Outlook & Benchmarks | Zayed Group', 'توقعات أسواق الخليج ومعايير الأداء لعام 2026 — مجموعة زايد | مجموعة زايد', 'Executive guide by Zayed Group covering Enterprise Turnkey Operations Retainer benchmarks in Bahrain.', 'دليل تنفيذي من مجموعة زايد حول معايير إدارة العمليات المؤسسية الشاملة في البحرين.', 'Insights', '{"all","insights","Manama","2026"}'::text[], 'Hana Yousef', 'published', now() - interval '6 days', true, now() - interval '6 days', now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO cms.faq (id, question_en, question_ar, answer_en, answer_ar, category, is_published, sort_order, created_at) VALUES ('faq-1', 'How quickly can Zayed Group initiate a Enterprise Turnkey Operations Retainer engagement?', 'كم يستغرق بدء تنفيذ خدمة إدارة العمليات المؤسسية الشاملة لدى مجموعة زايد؟', 'Discovery and kickoff begin within 48 hours of quotation sign-off, with a dedicated lead assigned in Manama.', 'يبدأ التخطيط والتنفيذ خلال 48 ساعة من اعتماد عرض السعر مع تعيين مدير حساب مخصص في Manama.', 'services', true, 1, now() - interval '45 days') ON CONFLICT (id) DO NOTHING;
