INSERT INTO cms.faq (id, question_en, question_ar, answer_en, answer_ar, category, is_published, sort_order, created_at) VALUES ('faq-6', 'Can our procurement team approve quotations and POs digitally?', 'هل يمكن لفريق المشتريات اعتماد العروض وأوامر الشراء إلكترونياً؟', 'Yes. Clients and internal approvers sign digitally with timestamped audit logs, PDF stamps, and QR verification.', 'نعم، يتاح التوقيع الرقمي والاعتماد الموثق بسجلات التدقيق والختم الإلكتروني ورمز التحقق QR.', 'approvals', true, 6, now() - interval '45 days') ON CONFLICT (id) DO NOTHING;
