INSERT INTO cms.article (id, slug, title_en, title_ar, excerpt_en, excerpt_ar, body_en, body_ar, body_html_en, body_html_ar, cover_url, seo_title_en, seo_title_ar, seo_description_en, seo_description_ar, category, tags, author_name, status, publish_at, featured, created_at, updated_at) VALUES ('art-11', 'zayed-group-sustainability-pledge', 'Practical Sustainability Targets for Bahrain Operations in 2026', 'مستهدفات الاستدامة العملية للعمليات في البحرين 2026', 'Key operational benchmarks, real metrics, and 2026 guidance from Zayed Group in Manama.', 'أبرز المعايير التشغيلية والأرقام الموثقة وإرشادات 2026 من مجموعة زايد في Manama.', '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Diversified Bahraini holding group operating retail storefronts, last-mile fleet logistics, media production, and enterprise advisory. Focusing on Enterprise Turnkey Operations Retainer, our teams help Gulf enterprises scale reliably."}]}]}'::jsonb, '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"مجموعة بحرينية متنوعة الأنشطة تدير المتاجر الإلكترونية والأسطول اللوجستي والإنتاج الإعلامي والاستشارات. من خلال خدمة إدارة العمليات المؤسسية الشاملة نساعد المؤسسات على النمو المستدام."}]}]}'::jsonb, '<p>Diversified Bahraini holding group operating retail storefronts, last-mile fleet logistics, media production, and enterprise advisory.</p><p>Focusing on <strong>Enterprise Turnkey Operations Retainer</strong>, our Manama specialists help Gulf organizations standardize turnaround times and audit transparency.</p>', '<p>مجموعة بحرينية متنوعة الأنشطة تدير المتاجر الإلكترونية والأسطول اللوجستي والإنتاج الإعلامي والاستشارات.</p><p>من خلال خدمة <strong>إدارة العمليات المؤسسية الشاملة</strong>، يعمل فريقنا في Manama على توحيد سرعة التسليم ووضوح التدقيق.</p>', '/api/files/media/banners/banner-02.png', 'Practical Sustainability Targets for Bahrain Operations in 2026 | Zayed Group', 'مستهدفات الاستدامة العملية للعمليات في البحرين 2026 | مجموعة زايد', 'Executive guide by Zayed Group covering Enterprise Turnkey Operations Retainer benchmarks in Bahrain.', 'دليل تنفيذي من مجموعة زايد حول معايير إدارة العمليات المؤسسية الشاملة في البحرين.', 'Sustainability', '{"all","sustainability","Manama","2026"}'::text[], 'Hana Yousef', 'published', now() - interval '66 days', false, now() - interval '66 days', now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO cms.faq (id, question_en, question_ar, answer_en, answer_ar, category, is_published, sort_order, created_at) VALUES ('faq-11', 'Can scope adjustments be added mid-project cleanly?', 'هل يمكن إضافة أو تعديل نطاق العمل أثناء تنفيذ المشروع؟', 'Any variation order generates a transparent delta quotation linked directly to the parent project and budget.', 'يتم إصدار ملحق تعديل واضح مرتبط مباشرة بميزانية المشروع الأساسية وموافقتكم.', 'changes', true, 11, now() - interval '45 days') ON CONFLICT (id) DO NOTHING;
