INSERT INTO cms.review (id, author_en, author_ar, company_en, company_ar, quote_en, quote_ar, rating, is_approved, sort_order, year, created_at) VALUES ('619d4643-0a52-41c0-a6d8-201076585b4d', 'Eng. Salman Al-Moayyed', 'م. سلمان المؤيد', 'Almoayyed Contracting Group W.L.L.', 'مجموعة المؤيد للمقاولات ذ.م.م', 'Zayed Group consistently delivers on complex Bahrain commercial schedules with transparent VAT documentation and responsive bilingual account leads.', 'تلتزم مجموعة زايد دائماً بالجداول الزمنية للمشاريع التجارية في البحرين مع توثيق ضريبي شفاف وفريق حسابات سريع الاستجابة.', 5, true, 20, 2026, now() - interval '15 days') ON CONFLICT (id) DO NOTHING;
INSERT INTO cms.review (id, author_en, author_ar, company_en, company_ar, quote_en, quote_ar, rating, is_approved, sort_order, year, created_at) VALUES ('882cbed9-071b-4dea-ae24-f4a8094f80a7', 'Dr. Hessa Al-Zayani', 'د. حصة الزياني', 'Dilmunia Health & Wellness Center', 'مركز دلمونيا للصحة والعافية', 'From initial quotation to final commissioning, the Zayed Group operations team exceeded our SLA expectations.', 'من عرض السعر الأولي حتى التسليم النهائي، تجاوز فريق عمليات مجموعة زايد توقعاتنا في الالتزام بمستوى الخدمة.', 5, true, 21, 2026, now() - interval '20 days') ON CONFLICT (id) DO NOTHING;
INSERT INTO cms.faq (id, question_en, question_ar, answer_en, answer_ar, category, is_published, sort_order, created_at) VALUES ('343a1b6f-74d3-49d4-ae3b-37c3e1ea23ca', 'Are all Zayed Group invoices compliant with Bahrain NBR 10% VAT regulations?', 'هل جميع فواتير مجموعة زايد متوافقة مع لوائح ضريبة القيمة المضافة 10% في البحرين؟', 'Yes. Every quotation and tax invoice includes our registered VAT ID (200010000100002), itemized tax calculations, and verifiable QR metadata.', 'نعم، تتضمن كل فاتورة ضريبية وعرض سعر رقمنا الضريبي المسجل (200010000100002) مع تفصيل الضريبة ورمز التحقق.', 'billing', true, 20, now() - interval '20 days') ON CONFLICT (id) DO NOTHING;
INSERT INTO cms.faq (id, question_en, question_ar, answer_en, answer_ar, category, is_published, sort_order, created_at) VALUES ('ec69b051-8506-48ba-a345-e474c5f1f0de', 'Which Bahrain governorates and GCC destinations do you cover?', 'ما هي المحافظات في البحرين ووجهات الخليج التي تغطونها؟', 'We provide same-day and next-day fulfillment across Capital, Muharraq, Northern, and Southern Governorates, plus scheduled cross-border freight to Saudi Arabia, UAE, Qatar, Kuwait, and Oman.', 'نوفر التوصيل في نفس اليوم أو اليوم التالي في جميع محافظات البحرين، بالإضافة إلى الشحن المجدول لدول مجلس التعاون الخليجي.', 'logistics', true, 21, now() - interval '23 days') ON CONFLICT (id) DO NOTHING;
